import{_ as a,a0 as d,w as r,s as u,ao as s,I as i,x as o,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150824 How to create an AP in Ubuntu 15.04 to connect to Android or iPhone","title":"如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP","tag":"201509","desc":""},"relativePath":"201509/20150824 How to create an AP in Ubuntu 15.04 to connect to Android or iPhone.md","filePath":"[post].md"}'),l={name:"201509/20150824 How to create an AP in Ubuntu 15.04 to connect to Android or iPhone.md"};function m(w,t,c,A,P,g){const n=d("Link");return r(),u("div",null,[t[13]||(t[13]=s(`<h1 id="如何在-ubuntu-15-04-下創建一個可供-android-ios-連接的-ap" tabindex="-1">如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP <a class="header-anchor" href="#如何在-ubuntu-15-04-下創建一個可供-android-ios-連接的-ap" aria-label="Permalink to “如何在 Ubuntu 15.04 下創建一個可供 Android/iOS 連接的 AP”">​</a></h1><p>我成功地在 Ubuntu 15.04 下用 Gnome Network Manager 創建了一個無線AP熱點。接下來我要分享一下我的步驟。請注意：你必須要有一個可以用來創建AP熱點的無線網卡。如果你不知道如何確認它的話，在終端(Terminal)裏輸入<code>iw list</code>。</p><p>如果你沒有安裝<code>iw</code>的話, 在Ubuntu下你可以使用<code>sudo apt-get install iw</code>進行安裝.</p><p>在你鍵入<code>iw list</code>之後, 查看“支持的接口模式”， 你應該會看到類似下面的條目中看到 AP:</p><pre><code>Supported interface modes:

* IBSS
* managed
* AP
* AP/VLAN
* monitor
* mesh point
</code></pre><p>讓我們一步步看：</p><p>1、 斷開WIFI連接。使用有線網絡接入你的筆記本。</p><p>2、 在頂欄面板裏點擊網絡的圖標 -&gt; Edit Connections(編輯連接) -&gt; 在彈出窗口裏點擊Add(新增)按鈕。</p><p>3、 在下拉菜單內選擇Wi-Fi。</p><p>4、 接下來：</p><p>a、 輸入一個鏈接名 比如: Hotspot 1</p><p>b、 輸入一個 SSID 比如: Hotspot 1</p><p>c、 選擇模式(mode): Infrastructure （基礎設施）</p><p>d、 設備 MAC 地址: 在下拉菜單裏選擇你的無線設備</p><p><img src="http://i2.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome1.jpg" alt=""></p><p>5、 進入Wi-Fi安全選項卡，選擇 WPA &amp; WPA2 Personal 並且輸入密碼。 6、 進入IPv4設置選項卡，在Method(方法)下拉菜單裏，選擇Shared to other computers(共享至其他電腦)。</p><p><img src="http://i1.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome4.jpg" alt=""></p><p>7、 進入IPv6選項卡，在Method(方法)裏設置為忽略ignore (只有在你不使用IPv6的情況下這麼做) 8、 點擊 Save(保存) 按鈕以保存配置。 9、 從 menu/dash 裏打開Terminal。 10、 修改你剛剛使用 network settings 創建的連接。</p><p>使用 VIM 編輯器:</p><pre><code>sudo vim /etc/NetworkManager/system-connections/Hotspot
</code></pre><p>或使用Gedit 編輯器:</p><pre><code>gksu gedit /etc/NetworkManager/system-connections/Hotspot
</code></pre><p>把名字 Hotspot 用你在第4步裏起的連接名替換掉。</p><p><img src="http://i2.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome2.jpg?resize=640%2C402" alt=""></p><p>a、 把 <code>mode=infrastructure</code> 改成 <code>mode=ap</code> 並且保存文件。 b、 一旦你保存了這個文件，你應該能在 Wifi 菜單裏看到你剛剛建立的AP了。(如果沒有的話請再頂欄裏 關閉/打開 Wifi 選項一次)</p><p><img src="http://i1.wp.com/www.linuxveda.com/wp-content/uploads/2015/08/ubuntu-ap-gnome3.jpg?resize=290%2C375" alt=""></p><p>11、你現在可以把你的設備連上Wifi了。已經過 Android 5.0的小米4測試。(下載了1GB的文件以測試速度與穩定性)</p><hr>`,28)),i("p",null,[t[1]||(t[1]=o("via: ",-1)),e(n,{href:"http://www.linuxveda.com/2015/08/23/how-to-create-an-ap-in-ubuntu-15-04-to-connect-to-androidiphone/"},{default:p(()=>[...t[0]||(t[0]=[o("http://www.linuxveda.com/2015/08/23/how-to-create-an-ap-in-ubuntu-15-04-to-connect-to-androidiphone/",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=o("作者：",-1)),e(n,{href:"http://www.linuxveda.com/author/sayantan_das/"},{default:p(()=>[...t[2]||(t[2]=[o("Sayantan Das",-1)])]),_:1}),t[6]||(t[6]=o(" 譯者：",-1)),e(n,{href:"https://github.com/Moelf"},{default:p(()=>[...t[3]||(t[3]=[o("Moelf",-1)])]),_:1}),t[7]||(t[7]=o(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原創翻譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[o("Linux中國",-1)])]),_:1}),t[12]||(t[12]=o(" 榮譽推出",-1))])])}const x=a(l,[["render",m]]);export{T as __pageData,x as default};
